// The web game's own sounds for the Unreal port: renders every variant of every definition in
// src/audio/library.js (the same synthesis the browser runs, seeded by name and variant, so the files are identical on
// every machine), plus the two reverb impulse responses of src/audio.js, and writes the definitions the Unreal audio
// subsystem reads.
//
// Usage: node tools/ue-export/audio.mjs [outDir]      (from the repository root)
//   outDir defaults to unreal/MurderInc/Content/Audio/Web (git-ignored: about 29 MB, regenerated by this script).
//
// Writes:
//   <outDir>/<name>_<nn>.wav      one file per variant (nn from 01), PCM 24-bit at the sound's native rate
//   <outDir>/IR_street.wav, IR_shop.wav   the reverb responses, stereo 48 kHz
//   unreal/MurderInc/Content/Data/audio_sounds.json   every definition: bus, variants, rate, measured length, peak,
//       volume, jitter, priority, max voices, gap, reference distance, roll-off, loop and stereo flags (spec 07 2.12)
//
// audio_sounds.json is generated: never edit it by hand. The hand-tuned mix, the event table and the replacement
// layers are in Content/Data/audio.json.

import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { SOUNDS, DEFAULT_SR, renderNow, renderOrder, variantsOf } from '../../src/audio/library.js';
import { impulse, seeded } from '../../src/audio/dsp.js';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = resolve(process.argv[2] || join(ROOT, 'unreal/MurderInc/Content/Audio/Web'));
const DATA = join(ROOT, 'unreal/MurderInc/Content/Data/audio_sounds.json');

/** PCM 24-bit little-endian WAV of float channels (clipped to full scale). */
function wav24(channels, sr) {
  const n = channels[0].length;
  const ch = channels.length;
  const data = n * ch * 3;
  const b = Buffer.alloc(44 + data);
  b.write('RIFF', 0); b.writeUInt32LE(36 + data, 4); b.write('WAVE', 8);
  b.write('fmt ', 12); b.writeUInt32LE(16, 16); b.writeUInt16LE(1, 20); b.writeUInt16LE(ch, 22);
  b.writeUInt32LE(sr, 24); b.writeUInt32LE(sr * ch * 3, 28); b.writeUInt16LE(ch * 3, 32); b.writeUInt16LE(24, 34);
  b.write('data', 36); b.writeUInt32LE(data, 40);
  let o = 44;
  for (let i = 0; i < n; i++) {
    for (let c = 0; c < ch; c++) {
      const v = Math.max(-1, Math.min(1, channels[c][i]));
      const s = Math.round(v * 8388607);
      b.writeIntLE(s, o, 3);
      o += 3;
    }
  }
  return b;
}

const pad = (i) => String(i).padStart(2, '0');

mkdirSync(OUT, { recursive: true });
const t0 = Date.now();
const sounds = {};
let files = 0;
let bytes = 0;
let clipped = 0;
for (const name of renderOrder()) {
  const def = SOUNDS[name];
  const n = variantsOf(name);
  const lengths = [];
  let peak = 0;
  for (let v = 0; v < n; v++) {
    const r = renderNow(name, v);
    for (const c of r.channels) for (let i = 0; i < c.length; i++) {
      const a = Math.abs(c[i]);
      if (a > peak) peak = a;
      if (a > 1) clipped++;
    }
    const buf = wav24(r.channels, r.sr);
    writeFileSync(join(OUT, `${name}_${pad(v + 1)}.wav`), buf);
    files++;
    bytes += buf.length;
    lengths.push(+(r.channels[0].length / r.sr).toFixed(4));
  }
  sounds[name] = {
    bus: def.bus,
    variants: n,
    sr: def.sr || DEFAULT_SR,
    secs: lengths,
    peak: def.peak || 0.8,
    measuredPeak: +peak.toFixed(4),
    vol: def.vol ?? 1,
    jitter: def.jitter ?? null,
    prio: def.prio ?? 5,
    max: def.max ?? 0,
    gap: def.gap ?? 0,
    ref: def.ref ?? null,
    roll: def.roll ?? null,
    loop: !!def.loop,
    stereo: !!def.stereo,
    pan: def.pan ?? 0,
  };
}

// The two reverb responses (src/audio.js 248-249): seeds 11 and 23, +31 for the right channel.
const IRS = [
  ['IR_street', 1.4, 11, { bright: 5200, dark: 700, early: [[0.021, 0.5], [0.047, 0.35], [0.083, 0.3], [0.131, 0.22], [0.19, 0.15]], density: 0.8 }],
  ['IR_shop', 0.8, 23, { bright: 7000, dark: 1600, early: [[0.007, 0.6], [0.013, 0.5], [0.019, 0.45], [0.026, 0.35]] }],
];
for (const [file, secs, seed, o] of IRS) {
  const ch = [0, 1].map((c) => impulse(48000, secs, seeded(seed + c * 31), o));
  // Unit energy per channel is far below full scale; scale both by the same factor so the file is audible and
  // record the factor so a convolution can undo it.
  let top = 0;
  for (const c of ch) for (let i = 0; i < c.length; i++) top = Math.max(top, Math.abs(c[i]));
  const g = 0.9 / top;
  for (const c of ch) for (let i = 0; i < c.length; i++) c[i] *= g;
  writeFileSync(join(OUT, `${file}.wav`), wav24(ch, 48000));
  sounds[file] = { bus: 'ir', variants: 1, sr: 48000, secs: [secs], peak: 0.9, unitEnergyScale: +(1 / g).toExponential(6), loop: false, stereo: true, file: `${file}.wav` };
  files++;
}

const doc = {
  meta: {
    file: 'audio_sounds.json',
    about: 'Generated by node tools/ue-export/audio.mjs from src/audio/library.js: every sound of the web game and how it plays (docs/unreal/spec/07-ui-audio.md 2.12). Files: Content/Audio/Web/<name>_<nn>.wav. Do not edit: the mix, the event table and the replacement layers are in audio.json.',
    generated: new Date().toISOString().slice(0, 10),
    names: Object.keys(sounds).length,
    files,
  },
  sounds,
};
mkdirSync(dirname(DATA), { recursive: true });
const lines = Object.entries(sounds).map(([k, v]) => `  ${JSON.stringify(k)}: ${JSON.stringify(v)}`);
writeFileSync(DATA, `{\n "meta": ${JSON.stringify(doc.meta, null, 2).replace(/\n/g, '\n ')},\n "sounds": {\n${lines.join(',\n')}\n }\n}\n`);
console.log(`AUDIO OK ${Object.keys(sounds).length} names, ${files} files, ${(bytes / 1048576).toFixed(1)} MB, ${clipped} samples above full scale, ${((Date.now() - t0) / 1000).toFixed(1)} s -> ${OUT}`);
